import{_ as i,c as n,o as t,ae as a}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"Establishing the National Energy Dominance Council","description":"","frontmatter":{"title":"Establishing the National Energy Dominance Council","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/02/establishing-the-national-energy-dominance-council/","publishDate":"2025-02-14T17:41:24-05:00"},"headers":[],"relativePath":"executive-orders/2025-02-14-establishing-the-national-energy-dominance-council.md","filePath":"executive-orders/2025-02-14-establishing-the-national-energy-dominance-council.md"}'),o={name:"executive-orders/2025-02-14-establishing-the-national-energy-dominance-council.md"};function l(r,e,s,c,h,u){return t(),n("div",null,e[0]||(e[0]=[a('<h1 id="establishing-the-national-energy-dominance-council" tabindex="-1">Establishing the National Energy Dominance Council <a class="header-anchor" href="#establishing-the-national-energy-dominance-council" aria-label="Permalink to &quot;Establishing the National Energy Dominance Council&quot;">​</a></h1><p>Published: Friday, February 14, 2025</p><ul><li>The executive order emphasizes the importance of expanding reliable and affordable energy production in the U.S.</li><li>Goals: <ul><li>Reduce inflation</li><li>Grow the economy</li><li>Create good-paying jobs</li><li>Reestablish American leadership in manufacturing and technology, particularly in artificial intelligence</li><li>Promote global peace by leveraging economic and diplomatic tools</li></ul></li><li>National assets to be utilized include: <ul><li>Crude oil, natural gas, coal, uranium, biofuels, and more</li></ul></li><li>The aim is to: <ul><li>Preserve natural beauty</li><li>Decrease dependency on foreign imports</li><li>Lower deficits and national debt</li></ul></li><li>Establishment of the <strong>National Energy Dominance Council</strong> within the Executive Office of the President, chaired by the Secretary of the Interior, with various other Secretaries and officials as members.</li><li>Responsibilities of the Council: <ul><li>Advise the President on energy production strategies and improvements in energy processes</li><li>Develop a <strong>National Energy Dominance Strategy</strong> to promote energy production and private sector investment</li><li>Facilitate cooperation between the federal government and private energy sectors</li></ul></li><li>The Council is tasked with raising public awareness about energy dominance and addressing regulatory issues affecting energy costs.</li><li>Collaboration and consultation with state, local, and tribal governments is encouraged to enhance energy production.</li><li>General provisions ensure that the order does not affect the existing authorities of executive agencies and must comply with applicable laws.</li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/02/establishing-the-national-energy-dominance-council/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/02/establishing-the-national-energy-dominance-council/</a></p>',4)]))}const m=i(o,[["render",l]]);export{g as __pageData,m as default};
